  "type": "module",
  "license": "MIT",
  "author": "Lu Cao (@caoool)",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "gpt-image",
    "openai",
    "image-generation",
    "text-to-image",
    "cli-proxy-api"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/caoool/opencode-gpt-image-plugin.git"
  },
  "homepage": "https://github.com/caoool/opencode-gpt-image-plugin#readme",
  "bugs": {
    "url": "https://github.com/caoool/opencode-gpt-image-plugin/issues"
  },
  "exports": {
    ".": "./src/index.js"
  },
  "main": "./src/index.js",
  "files": [
    "src",
    "skills",
    "commands",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=18"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.17.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.17.0"
  },
